head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gDutyID = js_duty;
scwin.vScrenID = 'ULDSTF39200.xml';
scwin.LastJob;
scwin.gOvrdue_occr_dd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gIsurCd;
scwin.gSDate; //연체발생 시작일
scwin.gEDate; //연체발생 종료일grd_Grid
scwin.gPeriodTp; //기간선택

//리사이징
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
frame.SetEvent("onwinstat", OnWinStat);
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    var gw;
    var ew;

    // GRID 처리
    grd_Grid.ReDraw = "false";
    gw = grd_Grid.getStyle("width");
    ew = a - parseInt(gw) - 35;
    grd_Grid.setGridWidth(parseInt(gw) + ew);
    grd_Grid.ReDraw = "true";
    try {
        if (grd_Grid2 != undefined) {
            grd_Grid2.setBroadcast("false");
            gw = grd_Grid2.style.getStyle("width");
            ew = a - parseInt(gw) - 35;
            grd_Grid2.style.setGridWidth(parseInt(gw) + ew);
            grd_Grid2.setBroadcast("true");
        }
    } catch (E) {

    }
    try {
        if (mgrd_Grid != undefined) {
            mgrd_Grid.setBroadcast("false");
            gw = mgrd_Grid.style.getStyle("width");
            ew = a - parseInt(gw) - 35;
            mgrd_Grid.style.setGridWidth(parseInt(gw) + ew);
            mgrd_Grid.setBroadcast("true");
        }
    } catch (E) {

    }


    // 공통엑셀저장버튼 처리
    try {
        btn_Excel.style.left = parseInt(btn_Excel.style.left) + ew;
    } catch (E) {

    }
    // 재무정보 화면도 리사이즈 적용(2009.10.30 PHJ)
    try {
        btn_Input.style.left = parseInt(btn_Input.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_New.style.left = parseInt(btn_New.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_save.style.left = parseInt(btn_save.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_Modify.style.left = parseInt(btn_Modify.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_Delete.style.left = parseInt(btn_Delete.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_Close.style.left = parseInt(btn_Close.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_Detail.style.left = parseInt(btn_Detail.style.left) + ew;
    } catch (E) {

    }


    // 상단공통패널부 처리
    __GROUPBOX_BACKGROUND__panel_1.style.setGridWidth(parseInt(gw) + ew);
    try {
        btn_Cancel.style.left = parseInt(btn_Cancel.style.left) + ew;
    } catch (E) {

    }
    try {
        btn_Search.style.left = parseInt(btn_Search.style.left) + ew;
    } catch (E) {

    }
    try {
        cmb_PerPage.style.left = parseInt(cmb_PerPage.style.left) + ew;
    } catch (E) {

    }
    try {
        image_11.style.left = parseInt(image_11.style.left) + ew;
    } catch (E) {

    }
    scwin.gOldWidthSize = frame.width;
};




// 시장구분 라디오버튼
scwin.fn_Init = function() {
    //시장구분 display none 셋팅 - 검색조건 추가시 제거
    //label_29.style.display = "none";
    //rdo_MKT_ID.style.display = "none";

    var y_day = $c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 1);
    $c.stf.setObjectValue(edt_SDate, y_day);
    $c.stf.setObjectValue(edt_EDate, y_day);
    $c.stf.setObjectValue(txb_ATTACH_FILE_NM, "");
    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();

    //삭제버튼 - 선택한 시장구분의 데이터를 삭제한다.(테스트를 위해 만들어 놓은 버튼으로써 항상 show false)로 처리
    $c.stf.showObj(btn_Del, false);
    //총회사수 - 총회사수를 구할 경우 정렬이 깨지는 현상이 있어 show false 처리
    $c.stf.showObj(txb_companyCnt, false);

    //상장구분
    combo_stat.setDisabled(false);
    combo_stat.addClass("TopCondition_01");
    if (js_market == "9" || js_market == "4") {
        //시장구분
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.addClass("TopCondition_Blue");

        //채권상장여부
        combo_bnd_stat.setDisabled(false);
        combo_bnd_stat.addClass("TopCondition_01");

        //주권상장구분
        combo_stat.setSelectedIndex(0);
        //채권상장여부
        combo_bnd_stat.setSelectedIndex(1);
        $c.stf.showObj(label_9, false);
    } else {
        // 콘트롤 잠그기

        //시장구분
        rdo_MKT_ID.setDisabled(true);
        $c.stf.showObj(label_29, false);
        $c.stf.showObj(rdo_MKT_ID, false);

        //주권상장구분
        combo_stat.setSelectedIndex(1);
        //채권상장여부
        combo_bnd_stat.setSelectedIndex(0);

        //combo_bnd_stat.Enable = false;
        //showObj(label_1, false);
        //showObj(combo_bnd_stat, false);

        //상장구분
        //combo_stat.Index = 1;
        //combo_stat.Enable = false;
        //showObj(label_2, false);
        //showObj(combo_stat, false);

    }
    if (js_market == '1') {
        //유가
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '(유)대규모기업여부');
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    } else if (js_market == '2') {
        //코스닥
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '(코)대기업여부');
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    } else if (js_market == '6') {
        //코넥스
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Show', false);
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    } else if (js_market == '4') {
        //채권상장공시팀
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '대기업여부');
        $c.stf.setObjectValue(rdo_MKT_ID, "0");
    } else if (js_market == '9') {
        //시스템
        //label_29.style.display = "";
        //rdo_MKT_ID.style.display = "";
        $c.stf.setObjectValue(rdo_MKT_ID, 0);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, "0");
    }
};



// 공시일자, 팀, 담당자 세팅
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();
    dts_Delete.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CORPBND_PRINCINT_INOUT";
    dts_Delete.Reset();
    dts_Delete.insertRow();
    $c.bns.getBusinessDay();
};
scwin.getBusinessDay = function() {
    //var url = "/CorpBndPrincInt.do?method=corpBeforeBusinessDate";


    //dts_businessday.DataID = encodeURI(url);

    //dts_businessday.Reset();

};

//조회 버튼
scwin.fn_Search = function() {
    var flag = $c.stf.getObjectValue(rdo_MKT_ID);
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate) == false) {
        return;
    }
    if (flag == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/CorpBndPrincInt.do?method=listCorpBndPrincInt";
    url += "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD); //법인코드
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDate); //연체발생일자 시작일
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDate); //연체발생일자 종료일
    url += "&LIST_STAT_CD=" + $c.cp.valueOfIndex(combo_stat, "Column2", combo_stat.getSelectedIndex()); //주권 상장구분
    url += "&LIST_STAT_CD_BND=" + $c.cp.valueOfIndex(combo_bnd_stat, "Column2", combo_bnd_stat.getSelectedIndex()); //채권 상장구분
    url += "&JS_MARKET=" + js_market; //로그인 사용자의 시장구분
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&EMP_NO=" + scwin.gEmpNo;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url);
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(eval(obj), "ACPT_NO");
};


// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
scwin.addMonth = function(y, m, d, n) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    var d = new Date(y, m, d);
    d.setMonth((d.getMonth() - 1) + n);
    var lastdate = 32 - (new Date(d.getYear(), d.getMonth(), 32).getDate());
    var today = new Date().getDate();
    d.setDate((today > lastdate) ? lastdate__today : X);
    return d;
};


//파일선택
scwin.fn_SelectAttach = function() {
    if (file.getValue() == "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};


//엑셀파일저장
scwin.fn_Save = function() {
    dts_master.setCellData(1, "REG_EMP_NO", js_emp_no);
    var file_nm = file.getValue();
    if (file_nm == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "파일업로드");
        $c.win.alert(msg);
        txb_ATTACH_FILE_NM.focus();
        return;
    }
    var suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if (suffix != 'xls') {
        $c.win.alert("확장자 'xls' 만 가능합니다.");
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    scwin.LastJob = "엑셀저장";
    trs_Save.Action = "/CorpBndPrincInt.do?method=registerCorpBndPrincInt" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInputMaster=dts_master,I:pFile=dts_FileList)";
    trs_Save.post();
};


//파일관련 데이터 clear
scwin.fn_fileDataClear = function() {
    dts_master.removeAll();
    dts_FileList.removeAll();
    dts_master.insertRow();
    dts_FileList.insertRow();
    $c.stf.setObjectValue(txb_ATTACH_FILE_NM, "");
    file.setValue("");
};



/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_ISUR_CD)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_ISUR_CD, arrPar[0].ISUR_CD);
    $c.stf.setObjectValue(txb_COM_NM, arrPar[0].ISUR_NM);
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    if (js_market == "4") {
        scwin.fn_GetPar = fn_GetParIsurCd;
        scwin.fn_SetPar = fn_SetParIsurCd;
        $c.bns.fn_PopIsurSearch(btn_ISUR_CD);
    } else if (js_market == "9") {
        scwin.fn_GetPar = fn_GetParIsurCd;
        scwin.fn_SetPar = fn_SetParIsurCd;
        $c.bns.fn_PopIsurSearch(btn_ISUR_CD);
    } else {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search(); //조회 버튼

};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료

    txb_TotalCnt.setValue("총건수 : " + rowcount);
    cnt = dts_Grid.getCellData(0, "COM_CNT");
    //alert("rowcount : " + rowcount + " : cnt : " + cnt);
    if (isNaN(cnt)) {
        cnt = "0";
    }
    //txb_companyCnt.value = "총회사수 : " + cnt;

};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "사채원리금 연체정보", "", "8"); //엑셀 다운로드

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '' || scwin.gDepCd == 'UPTEAM') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 
    if (scwin.gDepCd != '' && scwin.gDepCd != 'UPTEAM') {
        cmb_EmpList.trigger("onclick");
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.CopyDataSet(dts_dep, dts_dep1);
        scwin.fn_addDsclTeamAll(rowcount);
