scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == "CBPI_OVRDUE_OCCR_DD") {
        scwin.gOvrdue_occr_dd = dts_Grid.getCellData(row, "CBPI_OVRDUE_OCCR_DD");
        await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39202.gfm", scwin.gOvrdue_occr_dd.substring(0, 4) + "-" + scwin.gOvrdue_occr_dd.substring(4, 6) + "-" + scwin.gOvrdue_occr_dd.substring(6, 8) + " 등록내역", 300, 100, 680, 400, "window");
    } else if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_Grid.getCellData(row, "CBPI_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
