scwin.btn_Del_onclick = function() {
    if ($c.stf.getObjectValue(rdo_MKT_ID) != "0") {
        if (!confirm(rdo_MKT_ID.getText() + " 시장의 전체데이터가 삭제됩니다. \n삭제하시겠습니까?")) {
            return;
        }
        dts_Delete.setCellData(1, "CBPI_MKT_TP_CD", $c.stf.getObjectValue(rdo_MKT_ID));
        scwin.LastJob = "삭제";
        trs_delete.Action = "/CorpBndPrincInt.do?method=deleteCorpBndPrincInt" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_delete.KeyName = "toinb_dataid4";
        trs_delete.KeyValue = "JSP(I:pInputMaster=dts_Delete)";
        trs_delete.post();
    }
};
scwin.trs_delete_OnFail = function() {
    $c.win.alert("삭제" + " 실패");
    $c.stf.alert_error(trs_delete);
};
scwin.trs_delete_OnSuccess = function() {
    $c.win.alert("삭제" + " 성공");
    scwin.fn_Search(); //조회 버튼

};
